 1	// @vitest-environment jsdom
 2	
 3	/**
 4	 * Tests for gui/public/js/orchestrator-widgets.js — WP-010
 5	 *
 6	 * All acceptance criteria tested:
 7	 *   AC-1: renderStatusCard produces valid HTML with PID, elapsed time,
 8	 *         progress summary, and status badge.
 9	 *   AC-2: renderKillButton calls API.orchestratorKill() after a
10	 *         confirmation prompt and invokes the callback.
11	 *   AC-3: renderDismissButton calls API.orchestratorDismiss() and
12	 *         invokes the callback.
13	 *   AC-4: renderLogPreview auto-polls API.getRunLogEntries() and
14	 *         appends new events. Returns a cleanup function that stops polling.
15	 *   AC-5: renderProgressBadge maps lastAction to appropriate icon/color.
16	 *   AC-6: renderCliReference returns static HTML with the CLI commands
17	 *         reference.
18	 *   AC-7: All functions are accessible on the global OrchestratorWidgets
19	 *         object.
20	 *
21	 * Uses jsdom + vm.runInThisContext to load the browser-side script.
22	 * API and escapeHtml are set on globalThis before the script runs.
23	 */
24	
25	import { describe, it, expect, beforeAll, beforeEach, afterEach, vi, type Mock } from 'vitest';
26	import { readFileSync } from 'node:fs';
27	import { join } from 'node:path';
28	import vm from 'node:vm';
29	
30	// ---------------------------------------------------------------------------
31	// Load dependent scripts, then the widget library
32	// ---------------------------------------------------------------------------
33	
34	const publicDir = join(__dirname, '../../gui/public');
35	
36	const utilsJs   = readFileSync(join(publicDir, 'utils.js'),    'utf-8');
37	const widgetsJs = readFileSync(
38	  join(publicDir, 'js', 'orchestrator-widgets.js'),
39	  'utf-8',
40	);
41	
42	// ---------------------------------------------------------------------------
43	// Global type declarations
44	// ---------------------------------------------------------------------------
45	
46	declare global {
47	  // eslint-disable-next-line no-var
48	  var OrchestratorWidgets: {
49	    formatLogAction:     (entry: Record<string, unknown>) => string;
50	    renderStatusCard:    (entry: Record<string, unknown>) => string;
51	    renderKillButton:    (entryId: string, onDone: () => void) => HTMLButtonElement;
52	    renderDismissButton: (entryId: string, onDone: () => void) => HTMLButtonElement;
53	    renderLogPreview:    (container: HTMLElement, slug: string, filename: string) => () => void;
54	    renderProgressBadge: (lastAction: string | null | undefined) => string;
55	    renderCliReference:  () => string;
56	  };
57	  // eslint-disable-next-line no-var
58	  var API: Record<string, (...args: unknown[]) => Promise<unknown>>;
59	}
60	
61	// ---------------------------------------------------------------------------
62	// Setup: install utils.js globals, stub API, then load the widget script
63	// ---------------------------------------------------------------------------
64	
65	beforeAll(() => {
66	  // Install utils.js globals (escapeHtml etc.)
67	  vm.runInThisContext(utilsJs);
68	  // Stub API with placeholder methods; individual tests override as needed.
69	  (globalThis as Record<string, unknown>)['API'] = {
70	    orchestratorKill:    vi.fn().mockResolvedValue(null),
71	    orchestratorDismiss: vi.fn().mockResolvedValue(null),
72	    getRunLogEntries:    vi.fn().mockResolvedValue({ entries: [], totalLines: 0 }),
73	  };
74	  // Load the widget module.
75	  vm.runInThisContext(widgetsJs);
76	});
77	
78	// Restore fresh API mocks and reset timers between tests.
79	beforeEach(() => {
80	  (globalThis.API as Record<string, ReturnType<typeof vi.fn>>)['orchestratorKill']    = vi.fn().mockResolvedValue(null);
81	  (globalThis.API as Record<string, ReturnType<typeof vi.fn>>)['orchestratorDismiss'] = vi.fn().mockResolvedValue(null);
82	  (globalThis.API as Record<string, ReturnType<typeof vi.fn>>)['getRunLogEntries']    = vi.fn().mockResolvedValue({ entries: [], totalLines: 0 });
83	});
84	
85	afterEach(() => {
86	  vi.restoreAllMocks();
87	});
88	
89	// ---------------------------------------------------------------------------
90	// Helpers
91	// ---------------------------------------------------------------------------
92	
93	/**
94	 * Flush all pending microtask queues (Promise callbacks).
95	 * Looping several times handles multi-hop .then() chains.
96	 */
97	async function flushPromises(): Promise<void> {
98	  for (let i = 0; i < 5; i++) await Promise.resolve();
99	}

  1	/* ============================================================
  2	   js/orchestrator-widgets.js — Shared Orchestrator Widget Library
  3	   MCP Server Dashboard SPA
  4	
  5	   Provides reusable UI components for the orchestrator views.
  6	   Exposes a global OrchestratorWidgets namespace object.
  7	
  8	   Depends on: API (api-client.js), escapeHtml (utils.js)
  9	   ============================================================ */
 10	
 11	var OrchestratorWidgets = (function () {
 12	  'use strict';
 13	
 14	  // ------------------------------------------------------------------
 15	  // Internal helpers
 16	  // ------------------------------------------------------------------
 17	
 18	  /**
 19	   * Formats an elapsed time in milliseconds as a short human-readable string.
 20	   * @param {number} ms - Elapsed milliseconds.
 21	   * @returns {string} Formatted string (e.g. "42s", "3m", "2h").
 22	   */
 23	  function formatElapsed(ms) {
 24	    var secs = Math.round(ms / 1000);
 25	    if (secs < 60) return secs + 's';
 26	    var mins = Math.floor(secs / 60);
 27	    if (mins < 60) return mins + 'm';
 28	    return Math.floor(mins / 60) + 'h';
 29	  }
 30	
 31	  /**
 32	   * Returns CSS class suffix + display label for an effectiveStatus value.
 33	   * @param {string} status
 34	   * @returns {{ cls: string, label: string }}
 35	   */
 36	  function statusMeta(status) {
 37	    if (status === 'started') return { cls: 'started', label: 'Started'  };
 38	    if (status === 'dead')    return { cls: 'dead',    label: 'Dead'     };
 39	    return                           { cls: 'pending', label: 'Pending'  };
 40	  }
 41	
 42	  // ------------------------------------------------------------------
 43	  // renderStatusCard(entry) → string (HTML)
 44	  // ------------------------------------------------------------------
 45	
 46	  /**
 47	   * Renders a status card HTML string for a single queue entry.
 48	   *
 49	   * @param {object} entry - An enriched QueueEntry from the backend.
 50	   * @param {string} entry.effectiveStatus - 'pending' | 'started' | 'dead'
 51	   * @param {number} entry.pid             - OS process ID.
 52	   * @param {string} entry.startedAt       - ISO 8601 start timestamp.
 53	   * @param {string|null} entry.progress   - Latest JSONL progress summary.
 54	   * @returns {string} HTML string.
 55	   */
 56	  function renderStatusCard(entry) {
 57	    var meta     = statusMeta(entry.effectiveStatus || 'pending');
 58	    var pid      = entry.pid != null ? String(entry.pid) : '—';
 59	    var progress = entry.progress || null;
 60	
 61	    var elapsed = '';
 62	    if (entry.startedAt) {
 63	      try {
 64	        var diff = Date.now() - new Date(entry.startedAt).getTime();
 65	        if (!isNaN(diff) && diff >= 0) elapsed = formatElapsed(diff);
 66	      } catch (_) {}
 67	    }
 68	
 69	    var html = '<div class="orchestrator-status-card">';
 70	
 71	    // Header: status badge + elapsed time
 72	    html += '<div class="orchestrator-status-header">';
 73	    html += '<span class="badge badge-' + escapeHtml(meta.cls) + '">' +
 74	      escapeHtml(meta.label) + '</span>';
 75	    if (elapsed) {
 76	      html += ' <span class="text-muted orchestrator-elapsed">Running ' +
 77	        escapeHtml(elapsed) + '</span>';
 78	    }
 79	    html += '</div>';
 80	
 81	    // Body: PID + progress summary
 82	    html += '<div class="orchestrator-status-body">';
 83	    html += '<span class="text-muted orchestrator-pid">PID: ' +
 84	      escapeHtml(pid) + '</span>';
 85	    if (progress) {
 86	      html += '<div class="orchestrator-progress-summary">' +
 87	        escapeHtml(progress) + '</div>';
 88	    }
 89	    html += '</div>';
 90	
 91	    html += '</div>';
 92	    return html;
 93	  }
 94	
 95	  // ------------------------------------------------------------------
 96	  // renderKillButton(entryId, onDone) → HTMLButtonElement
 97	  // ------------------------------------------------------------------
 98	
 99	  /**
100	   * Creates a "Kill" button that, on click, asks for confirmation then

100	   * Creates a "Kill" button that, on click, asks for confirmation then
101	   * calls API.orchestratorKill(entryId).  Invokes onDone() on success.
102	   *
103	   * @param {string}   entryId - Queue entry UUID.
104	   * @param {Function} onDone  - Callback invoked after a successful kill.
105	   * @returns {HTMLButtonElement}
106	   */
107	  function renderKillButton(entryId, onDone) {
108	    var btn = document.createElement('button');
109	    btn.type = 'button';
110	    btn.className = 'btn btn-danger btn-sm orchestrator-kill-btn';
111	    btn.textContent = 'Kill';
112	
113	    btn.addEventListener('click', function () {
114	      if (!window.confirm(
115	        'Kill this orchestrator run? The process will receive SIGTERM.'
116	      )) {
117	        return;
118	      }
119	      API.orchestratorKill(entryId).then(function () {
120	        if (typeof onDone === 'function') onDone();
121	      }).catch(function (err) {
122	        window.alert(
123	          'Failed to kill run: ' +
124	          ((err && err.message) || String(err))
125	        );
126	      });
127	    });
128	
129	    return btn;
130	  }
131	
132	  // ------------------------------------------------------------------
133	  // renderDismissButton(entryId, onDone) → HTMLButtonElement
134	  // ------------------------------------------------------------------
135	
136	  /**
137	   * Creates a "Dismiss" button that calls API.orchestratorDismiss(entryId).
138	   * Invokes onDone() on success.  Intended for 'dead' queue entries.
139	   *
140	   * @param {string}   entryId - Queue entry UUID.
141	   * @param {Function} onDone  - Callback invoked after a successful dismiss.
142	   * @returns {HTMLButtonElement}
143	   */
144	  function renderDismissButton(entryId, onDone) {
145	    var btn = document.createElement('button');
146	    btn.type = 'button';
147	    btn.className = 'btn btn-secondary btn-sm orchestrator-dismiss-btn';
148	    btn.textContent = 'Dismiss';
149	
150	    btn.addEventListener('click', function () {
151	      API.orchestratorDismiss(entryId).then(function () {
152	        if (typeof onDone === 'function') onDone();
153	      }).catch(function (err) {
154	        window.alert(
155	          'Failed to dismiss entry: ' +
156	          ((err && err.message) || String(err))
157	        );
158	      });
159	    });
160	
161	    return btn;
162	  }
163	
164	  // ------------------------------------------------------------------
165	  // formatLogAction(entry) → string
166	  // ------------------------------------------------------------------
167	
168	  /**
169	   * Maps a raw JSONL log entry object to a human-friendly display string
170	   * for use in the log preview widget.
171	   *
172	   * The mapping is:
173	   *   run_start        → "Starting the run"
174	   *   stage_start      → "Starting stage: {stage}"
175	   *   stage_complete   → "Stage complete: {stage}"
176	   *   progress_snapshot→ "Progress snapshot"
177	   *   tool_call        → "Tool call: {tool_name}"  (or "Tool call" if no tool_name)
178	   *   wp_complete      → "Work package complete: {wp_id}"
179	   *   wp_status_change → "WP status → {new_status}"
180	   *   run_end          → "Run ended"
181	   *   run_error        → "Run error"
182	   *   signal_shutdown  → "Interrupted by signal"
183	   *   heartbeat        → "Heartbeat"
184	   *   mcp_error        → "MCP error"
185	   *   route            → "Routing decision"
186	   *   <unknown>        → title-cased version of the raw action, or JSON fallback
187	   *
188	   * NOTE: This function is intentionally scoped to the log preview only.
189	   * It does NOT affect renderProgressBadge, which continues to use the
190	   * raw action string.
191	   *
192	   * @param {object|null|undefined} entry - A JSONL log entry object. Null and
193	   *   undefined are safely handled: a falsy entry (or an entry without an
194	   *   `action` field) falls through to `JSON.stringify(entry)` as the
195	   *   last-resort fallback.
196	   * @returns {string} Human-friendly display label.
197	   */
198	  function formatLogAction(entry) {
199	    var action = (entry && entry.action) ? String(entry.action) : '';
200	
201	    switch (action) {
202	      case 'run_start':
203	        return 'Starting the run';
204	
205	      case 'stage_start':
206	        return 'Starting stage: ' + (entry.stage || '');
207	
208	      case 'stage_complete':
209	        return 'Stage complete: ' + (entry.stage || '');
210	
211	      case 'progress_snapshot':
212	        return 'Progress snapshot';
213	
214	      case 'tool_call':
215	        return entry.tool_name
216	          ? 'Tool call: ' + String(entry.tool_name)
217	          : 'Tool call';
218	
219	      case 'wp_complete':
220	        return 'Work package complete: ' + (entry.wp_id || '');
221	
222	      case 'wp_status_change':
223	        return 'WP status \u2192 ' + (entry.new_status || '');
224	
225	      case 'run_end':
226	        return 'Run ended';
227	
228	      case 'run_error':
229	        return 'Run error';
230	
231	      case 'signal_shutdown':
232	        return 'Interrupted by signal';
233	
234	      case 'heartbeat':
235	        return 'Heartbeat';
236	
237	      case 'mcp_error':
238	        return 'MCP error';
239	
240	      case 'route':
241	        return 'Routing decision';
242	
243	      default:
244	        if (action) {
245	          // Title-case the raw action string (replace underscores with spaces).
246	          return action
247	            .replace(/_/g, ' ')
248	            .replace(/\b\w/g, function (ch) { return ch.toUpperCase(); });
249	        }
250	        return JSON.stringify(entry);
251	    }
252	  }
253	
254	  // ------------------------------------------------------------------
255	  // renderLogPreview(container, slug, filename) → cleanup()
256	  // ------------------------------------------------------------------
257	
258	  /**
259	   * Starts auto-polling the run log for a queue entry and prepends new
260	   * JSONL events to `container` as they arrive, keeping the most-recent
261	   * entry at the top (most-recent-first ordering).
